@isTest private class DatabaseRequestFieldEvidenceTest {
 @isTest static void leadConvertFieldsWitness() {
  Database.LeadConvert convert = new Database.LeadConvert();
  convert.accountid = '001000000000001AAA';
  convert.contactid = '003000000000001AAA';
  convert.leadid = '00Q000000000001AAA';
  convert.opportunityid = '006000000000001AAA';
  convert.opportunityname = 'Opp Name';
  convert.overwriteleadsource = true;
  convert.ownerid = '005000000000001AAA';
  convert.relatedpersonaccountid = '001000000000002AAA';
  convert.sendnotificationemail = false;
  System.assertEquals('001000000000001AAA', convert.accountid);
  System.assertEquals('003000000000001AAA', convert.contactid);
  System.assertEquals('00Q000000000001AAA', convert.leadid);
  System.assertEquals('006000000000001AAA', convert.opportunityid);
  System.assertEquals('Opp Name', convert.opportunityname);
  System.assertEquals(true, convert.overwriteleadsource);
  System.assertEquals('005000000000001AAA', convert.ownerid);
  System.assertEquals('001000000000002AAA', convert.relatedpersonaccountid);
  System.assertEquals(false, convert.sendnotificationemail);
 }
 @isTest static void mergeRequestFieldsWitness() {
  Account master = new Account(Name = 'Master');
  Database.MergeRequest request = new Database.MergeRequest();
  request.masterrecord = master;
  request.recordtomergeids = new List<String>{'001000000000001AAA', '001000000000002AAA'};
  request.additionalinformationmap = new List<Datacloud.AdditionalInformationMap>();
  System.assertEquals(master, request.masterrecord);
  System.assertEquals(2, request.recordtomergeids.size());
  System.assertEquals(0, request.additionalinformationmap.size());
 }
}
